package com.dukaops.backend.sales;
import java.util.*; import java.math.BigDecimal; import org.springframework.data.domain.*; import org.springframework.data.jpa.repository.*; import org.springframework.data.repository.query.Param;
public interface SalesOrderRepository extends JpaRepository<SalesOrder,UUID>, org.springframework.data.jpa.repository.JpaSpecificationExecutor<SalesOrder>{ Optional<SalesOrder> findByTenant_IdAndIdempotencyKey(UUID tenantId,String key); Optional<SalesOrder> findByTenant_IdAndId(UUID tenantId,UUID id); @Query("select o from SalesOrder o where o.tenant.id=:tenantId and (lower(o.customerName) like lower(concat('%',:search,'%')) or lower(o.idempotencyKey) like lower(concat('%',:search,'%'))) order by o.createdAt desc") Page<SalesOrder> search(@Param("tenantId")UUID tenantId,@Param("search")String search,Pageable pageable); @Query("select o from SalesOrder o where o.tenant.id=:tenantId and o.status=:status and (lower(o.customerName) like lower(concat('%',:search,'%')) or lower(o.idempotencyKey) like lower(concat('%',:search,'%'))) order by o.createdAt desc") Page<SalesOrder> searchByStatus(@Param("tenantId")UUID tenantId,@Param("status")OrderStatus status,@Param("search")String search,Pageable pageable); Page<SalesOrder> findByTenant_Id(UUID tenantId,Pageable pageable); Page<SalesOrder> findByTenant_IdAndStatus(UUID tenantId,OrderStatus status,Pageable pageable); @Query("select coalesce(sum(o.totalAmount),0) from SalesOrder o where o.tenant.id=:tenantId and o.status='COMPLETED'") BigDecimal completedRevenue(@Param("tenantId")UUID tenantId); long countByTenant_IdAndStatus(UUID tenantId,OrderStatus status); }
